pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, IERC1271} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Signer signer;
    MockToken token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        signer = new Signer();
        token = new MockToken();
    }

    function testFuzz_property(bool isLong, uint256 duration, uint256 ts, uint256 nonce) public {
        vm.assume(ts > 1 && ts < type(uint256).max - 1001 days);
        duration = bound(duration, 0, 10_000 days - 1);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(signer),
            isCall: false,
            isLong: isLong,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: ts + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        vm.warp(ts);
        c.fillOrder(order, "", floorAssetTokenIds);

        uint256 longPositionId = uint256(c.hashOrder(order));

        // General rule: for every long order, the long position's expiration is
        // recorded at uint256(hashOrder(order)) and equals block.timestamp + duration.
        assertTrue(!isLong || c.positionExpirations(longPositionId) == ts + duration);
    }
}

